'use strict';
// Isolated in-memory demo: no network requests, localStorage or production writes.
const view=document.body.dataset.view;
const profiles=[{name:'FLUX.2 klein 4B',width:1024,steps:4,note:'FP8 蒸馏版 · 建议 4 步 · 适合本机 16GB 显存'},{name:'Z-Image-Turbo',width:1024,steps:9,note:'蒸馏工作流 · 建议 9 步 · 更高步数不一定改善质量'},{name:'Qwen-Image 2.1',width:768,steps:25,note:'INT8 稳定配置 · 中文提示词 · 首次 CPU 编码较慢'},{name:'SDXL Turbo',width:512,steps:4,note:'快速草稿 · 可尝试 1–4 步 · 优先英文提示词'}];
const artworks=[{file:'assets/flux2.png',width:1024,height:1024,model:'FLUX.2 klein 4B',steps:4,time:'31.76 秒',title:'晨光里的橘猫',prompt:'A small orange cat beside a blue ceramic vase, morning light, detailed photograph',liked:true},{file:'assets/qwen.png',width:768,height:768,model:'Qwen-Image 2.1',steps:25,time:'67.27 秒',title:'蓝色花瓶与猫',prompt:'A small orange cat sitting beside a blue ceramic vase, morning light, detailed photograph',liked:false}];
let tasks=[{prompt:'晨光里的橘猫，蓝色陶瓷花瓶',model:'FLUX.2 klein 4B',status:'已完成'},{prompt:'窗边的静物，柔和自然光',model:'FLUX.2 klein 4B',status:'已完成'},{prompt:'山间的小屋，清晨薄雾与松树',model:'Qwen-Image 2.1',status:'生成中'},{prompt:'雨后的街角，路灯和湿润的石板',model:'FLUX.2 klein 4B',status:'等待中'},{prompt:'海边的白色建筑，夏日午后',model:'FLUX.2 klein 4B',status:'等待中'}];
let paused=false,selectedArt=0,filter='all';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${({layers:'<path d="m12 3 9 5-9 5-9-5zM3 12l9 5 9-5M3 16l9 5 9-5"/>',star:'<path d="m12 3 3 6 6 1-4 5 1 6-6-3-6 3 1-6-4-5 6-1z"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>'})[n]}</svg>`;
function toast(s){const el=document.querySelector('.toast');el.textContent=s;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,4500);}
function syncImageMetadata(){
    document.querySelectorAll('.art').forEach(el=>{const a=artworks[Number(el.querySelector('[data-art]').dataset.art)];el.querySelector('.art-info small').textContent=`${a.model} · ${a.width} × ${a.height}`;});
    const caption=document.querySelector('.preview-model');
    if(caption){const a=artworks[selectedArt];caption.textContent=`${a.model} · ${a.width} × ${a.height} · 1:1`;}
    if(document.getElementById('details')?.open){document.querySelector('.detail-grid dl').querySelectorAll('dd')[2].textContent=`${artworks[selectedArt].width} × ${artworks[selectedArt].height} · 1:1`;}
}
const nav=`<div class="proto-bar"><span>HTML 交互原型 · 演示数据，不操作真实队列</span><nav aria-label="设计方案"><a href="index.html">方案概览</a>${[['workbench','a-workbench.html','A 专注'],['gallery','b-gallery.html','B 作品'],['batch','c-batch.html','C 批量']].map(([v,url,label])=>`<a href="${url}" ${view===v?'aria-current="page"':''}>${label}</a>`).join('')}</nav></div>`;
const header=`<header class="app-header"><div class="row between"><div class="wordmark">${icon('layers')}<div><h1>本地绘图工作台</h1><small>Local Image Studio</small></div></div><div class="row"><span class="live"><i></i>本地服务 · 演示</span><span class="tag">RTX 5070 Ti · 16GB</span></div></div></header>`;
function composer(kind='full'){return `<section class="compose panel"><div class="stack">${kind!=='inspector'?`<div class="editor-heading"><div><h2>${view==='batch'?'新建生成批次':'开始创作'}</h2><small>每行一个提示词，按需重复抽奖。</small></div><span class="tag">批量</span></div>`:''}${kind!=='input'?`<div class="field model-field"><label for="model">生图模型</label><select id="model" class="model">${profiles.map((p,i)=>`<option value="${i}">${p.name}</option>`).join('')}</select><p class="advice model-note"></p><small>切换同步更新等待任务，当前生成保持原模型。</small></div>`:''}${kind!=='inspector'?`<div class="field prompt-field"><label for="prompts">提示词</label><textarea id="prompts" class="prompts">晨光里的橘猫，蓝色陶瓷花瓶，写实摄影&#10;山间的小屋，清晨薄雾与松树&#10;雨后的街角，路灯和湿润的石板</textarea><small>示例输入，可自由编辑。任务只加入演示队列。</small></div>`:''}${kind!=='input'?`<div><div class="row between"><h3>生成配方</h3><button class="quiet" data-action="recommend">恢复推荐</button></div><div class="parameters" style="margin-top:16px"><div class="field"><label for="size">尺寸与比例</label><select id="size" class="size"></select></div><div class="field"><label for="count">每条抽奖数量</label><input id="count" class="count" type="number" min="1" max="100" value="3"></div><div class="field"><label for="steps">推理步数</label><input id="steps" class="steps" type="number" min="1" max="100" value="4"></div><div class="field"><label for="cfg">CFG</label><input id="cfg" class="cfg" type="number" min="0" max="30" step="0.5" value="1"></div></div><p class="advice recommendation"></p></div><details class="advanced"><summary>种子与提示词前后缀</summary><div class="parameters"><div class="field"><label for="seed">种子 · −1 随机</label><input id="seed" class="seed" type="number" min="-1" value="-1"></div><div class="field"><label for="prefix">前缀</label><input id="prefix" placeholder="如：高质量摄影"></div><div class="field"><label for="suffix">后缀</label><input id="suffix" placeholder="如：自然光"></div></div><p class="advice">固定种子逐张递增；随机种子每张独立。</p></details>`:''}${kind!=='inspector'?`<details class="history"><summary>提示词历史 <span class="muted">2 个示例批次</span></summary><div class="history-list"><button data-history="城市夜景，细雨中的霓虹">城市夜景与窗边静物<br><small>示例批次 · 点击载入</small></button><button data-history="海边的白色建筑，夏日午后">海边的白色建筑<br><small>示例批次 · 点击载入</small></button><button data-action="history-clear">清空演示历史</button></div></details><div class="dispatch"><button class="primary" data-action="add">${icon('plus')} <span class="add-label">加入 9 个任务</span></button><button data-action="input-clear">清空</button></div>`:''}</div></section>`;}
function queue(){return `<section class="queue panel" id="queue"><div class="panel-heading"><h2>生成队列 <span class="tag queue-count"></span></h2><small class="queue-state"></small></div><div class="queue-tools"><button data-action="pause">暂停</button><button data-action="shuffle">打乱等待</button><button data-action="stop">停止当前</button><button data-action="clear">清空队列</button></div><div class="queue-progress"><div class="row between"><small>批次进度</small><small class="queue-progress-label"></small></div><div class="track"><span></span></div></div><div class="queue-list"></div><p class="advice">清空只移除任务记录，作品保留。</p></section>`;}
function gallery(){return `<section class="artworks" id="artworks"><div class="panel-heading"><div><h2>作品集</h2><small>2 张实际模型测试图 · 仅用于布局演示</small></div><div class="gallery-tools"><button data-filter="all" class="active">全部</button><button data-filter="liked">收藏</button><button data-filter="hide">隐藏点踩</button><button data-action="export">导出</button></div></div><div class="collection"></div></section>`;}
function preview(){return `<section class="preview"><div class="panel-heading"><h2>最新作品</h2><div class="row"><button data-action="detail">查看详情</button><button class="star" data-like="0" aria-label="收藏这张图片" aria-pressed="true">${icon('star')}</button></div></div><div class="preview-stage"><img class="main-image" src="${artworks[0].file}" alt="实际测试图：橘猫和蓝色花瓶" data-art="0"></div><div class="preview-footer row between"><div><h3 class="preview-title">晨光里的橘猫</h3><small class="preview-model">FLUX.2 klein 4B · 1024 × 1024 · 1:1</small></div><button data-action="regen">${icon('arrow')} 再抽一张</button></div><div class="thumbs">${artworks.map((a,i)=>`<button data-preview="${i}" class="${i===0?'selected':''}" aria-label="预览 ${a.model}"><img src="${a.file}" alt="${a.title}"></button>`).join('')}</div></section>`;}
const service=`<footer class="service-bar"><span>本地引擎 · ComfyUI <span class="muted">/ 服务操作收纳于此</span></span><div class="row"><button data-action="logs">系统日志</button><button data-action="folder">本地目录</button><button data-action="service">重启 / 停止服务</button><button data-action="language">EN</button></div></footer>`;
let layout;
if(view==='workbench')layout=`<main class="workbench-grid">${composer()}${preview()}${queue()}</main><div class="lower-gallery">${gallery()}</div>`;
if(view==='gallery')layout=`<div class="gallery-shell"><aside class="rail"><div class="rail-title">浏览室</div><a href="#artworks">全部作品</a><button data-action="favorites">我的收藏</button><a href="#queue">生成队列</a><button data-action="create">新建创作</button><small>图片是主角。<br>参数只在创作时出现。</small></aside><main class="gallery-view"><div class="view-room"><header class="row between"><div><h2>挑出值得留下的画面。</h2><p class="muted">从结果出发，浏览、收藏，再生成。</p></div><button class="primary" data-action="create">${icon('plus')} 新建创作</button></header><div class="gallery-create">${composer()}</div>${gallery()}</div>${queue()}</main></div>`;
if(view==='batch')layout=`<nav class="batch-nav" aria-label="工作区导航"><a href="#batch">批次作业</a><a href="#artworks">生成作品</a><button class="quiet" data-action="logs">执行日志</button></nav><main id="batch"><div class="batch-layout"><div class="ledger">${composer('input')}<div class="batch-sheet"><header class="row between"><div><h2>当前批次 · 风景与静物</h2><small>提示词、模型与执行状态集中在一张作业表里。</small></div><span class="tag">示例批次</span></header>${queue()}</div></div><aside class="inspector"><div class="panel-heading"><h2>作业检查器</h2><span class="tag">模型联动</span></div>${composer('inspector')}</aside></div><div class="batch-output">${gallery()}</div></main>`;
document.body.classList.add(`${view}-view`);
document.getElementById('app').innerHTML=nav+header+layout+service+`<dialog id="details"><div class="row between"><h2>图片详情</h2><button data-action="close-detail" aria-label="关闭详情">${icon('close')}</button></div><div class="detail-grid"></div></dialog><div class="toast" role="status" hidden></div>`;
function renderQueue(){const finished=tasks.filter(t=>['已完成','已跳过'].includes(t.status)).length;document.querySelector('.queue-count').textContent=`${tasks.filter(t=>['生成中','等待中'].includes(t.status)).length} 个活动任务`;document.querySelector('.queue-state').textContent=(paused?'已暂停':'运行中')+' · 演示';document.querySelector('[data-action=pause]').textContent=paused?'恢复':'暂停';document.querySelector('.queue-progress-label').textContent=`${finished} / ${tasks.length}`;document.querySelector('.track span').style.width=`${tasks.length?finished/tasks.length*100:0}%`;document.querySelector('.queue-list').innerHTML=tasks.map((t,i)=>`<article class="queue-item ${t.status==='生成中'?'current':''}"><div class="row between"><span class="tag">${t.status}</span><small>${String(i+1).padStart(2,'0')}</small></div><p>${esc(t.prompt)}</p><small>${esc(t.model)}${t.status==='生成中'?' · 当前任务不随模型切换':''}</small>${t.status==='等待中'?`<div class="task-ops"><button data-front="${i}">置顶</button><button data-skip="${i}">跳过</button><button data-delete="${i}">删除</button></div>`:''}</article>`).join('')||'<p class="advice">还没有任务。在创作区加入一批提示词开始。</p>';}
function renderGallery(){document.querySelector('.collection').innerHTML=artworks.map((a,i)=>(filter==='liked'&&!a.liked)||(filter==='hide'&&a.disliked)?'':`<article class="art"><div class="art-image"><button data-art="${i}" aria-label="查看 ${a.title} 详情"><img src="${a.file}" alt="${a.title} · ${a.model} 实际测试输出" loading="lazy"></button></div><div class="art-info"><div><h3>${a.title}</h3><small>${a.model} · 1024 × 1024</small></div><button class="star" data-like="${i}" aria-label="收藏 ${a.title}" aria-pressed="${a.liked}">${icon('star')}</button></div></article>`).join('');document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));}
function setRecipe(){const p=profiles[Number(document.querySelector('.model').value)];document.querySelector('.steps').value=p.steps;document.querySelector('.cfg').value=1;const b=p.width;document.querySelector('.size').innerHTML=[`${b}x${b}`,`${b}x${b*3/4}`,`${b*3/4}x${b}`,`${b===1024?1280:b===768?1024:768}x${b===1024?720:b===768?576:432}`].map((s,i)=>{const [w,h]=s.split('x');return `<option value="${s}">${w} × ${h} · ${['1:1','4:3','3:4','16:9'][i]}${i===0?' · 推荐':''}</option>`;}).join('');document.querySelector('.model-note').textContent=p.note;document.querySelector('.recommendation').textContent=`建议 ${b} × ${b} · ${p.steps} 步 · CFG 1，可手动调整。`;}
function updateCount(){const lines=document.querySelector('.prompts').value.split('\n').filter(s=>s.trim()).length;document.querySelector('.add-label').textContent=`加入 ${lines*Number(document.querySelector('.count').value)} 个任务`;}
function details(i){selectedArt=i;const a=artworks[i];document.querySelector('.detail-grid').innerHTML=`<img src="${a.file}" alt="${a.title}"><div class="stack"><dl><dt>生图模型</dt><dd>${a.model}</dd><dt>提示词</dt><dd>${a.prompt}</dd><dt>分辨率</dt><dd>1024 × 1024 · 1:1</dd><dt>推理步数</dt><dd>${a.steps}</dd><dt>CFG / 种子</dt><dd>1 / 0</dd><dt>首次耗时</dt><dd>${a.time}（含加载）</dd></dl><small>本机实际测试输出，不属于演示队列。</small><div class="row"><a href="${a.file}" download>下载图片</a><button data-action="regen">再抽一张</button><button data-action="dislike">点踩 / 隐藏</button></div></div>`;document.getElementById('details').showModal();}
document.addEventListener('change',e=>{if(e.target.matches('.model')){setRecipe();const name=profiles[Number(e.target.value)].name;let n=0;tasks.forEach(t=>{if(t.status==='等待中'){t.model=name;n++;}});renderQueue();toast(`演示：${n} 个等待任务已切换到 ${name}`);}updateCount();});
document.addEventListener('input',e=>{if(e.target.matches('.prompts,.count'))updateCount();});
document.addEventListener('click',e=>{const b=e.target.closest('button');const art=e.target.closest('[data-art]');if(art){details(Number(art.dataset.art));return;}if(!b)return;if(b.dataset.like!==undefined){const i=Number(b.dataset.like);artworks[i].liked=!artworks[i].liked;renderGallery();b.setAttribute('aria-pressed',String(artworks[i].liked));return;}if(b.dataset.preview!==undefined){selectedArt=Number(b.dataset.preview);const a=artworks[selectedArt];document.querySelector('.main-image').src=a.file;document.querySelector('.main-image').dataset.art=selectedArt;document.querySelector('.preview-title').textContent=a.title;document.querySelector('.preview-model').textContent=`${a.model} · 1024 × 1024 · 1:1`;document.querySelectorAll('[data-preview]').forEach(el=>el.classList.toggle('selected',Number(el.dataset.preview)===selectedArt));const star=document.querySelector('.preview [data-like]');star.dataset.like=selectedArt;star.setAttribute('aria-pressed',String(a.liked));return;}if(b.dataset.filter){filter=b.dataset.filter;renderGallery();return;}if(b.dataset.history){document.querySelector('.prompts').value=b.dataset.history;updateCount();toast('已载入示例历史');return;}for(const op of ['front','skip','delete'])if(b.dataset[op]!==undefined){const i=Number(b.dataset[op]);if(op==='front')tasks.unshift(...tasks.splice(i,1));if(op==='skip')tasks[i].status='已跳过';if(op==='delete')tasks.splice(i,1);renderQueue();return;}
switch(b.dataset.action){case 'add':{const countEl=document.querySelector('.count');const count=Number(countEl.value);if(!Number.isInteger(count)||count<1||count>100){toast('抽奖数量须为 1–100 的整数');break;}const prompts=document.querySelector('.prompts').value.split('\n').filter(s=>s.trim());if(!prompts.length||prompts.length*count>1000){toast('请输入提示词，每批最多 1000 张');break;}const model=profiles[Number(document.querySelector('.model').value)].name;for(const prompt of prompts)for(let i=0;i<count;i++)tasks.push({prompt,model,status:'等待中'});renderQueue();toast(`已加入 ${prompts.length*count} 个演示任务，没有调用真实生图服务。`);break;}case 'recommend':setRecipe();toast('已恢复推荐值');break;case 'pause':paused=!paused;renderQueue();break;case 'shuffle':{const slots=tasks.map((t,i)=>t.status==='等待中'?i:-1).filter(i=>i>=0);const waiting=slots.map(i=>tasks[i]);for(let i=waiting.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[waiting[i],waiting[j]]=[waiting[j],waiting[i]];}slots.forEach((s,i)=>tasks[s]=waiting[i]);renderQueue();toast('已打乱等待任务，当前生成不变。');break;}case 'clear':tasks=tasks.filter(t=>t.status==='生成中');renderQueue();toast('队列已清空，图片保留，当前生成继续。');break;case 'stop':tasks.forEach(t=>{if(t.status==='生成中')t.status='已跳过';});paused=true;renderQueue();break;case 'input-clear':document.querySelector('.prompts').value='';updateCount();break;case 'history-clear':document.querySelector('.history-list').innerHTML='<p class="advice">历史为空，加入批次后会保留提示词。</p>';break;case 'detail':details(selectedArt);break;case 'close-detail':document.getElementById('details').close();break;case 'create':document.querySelector('.gallery-create').classList.toggle('open');break;case 'favorites':filter='liked';renderGallery();break;case 'regen':document.querySelector('.prompts').value=artworks[selectedArt].prompt;updateCount();if(view==='gallery')document.querySelector('.gallery-create').classList.add('open');if(document.getElementById('details').open)document.getElementById('details').close();toast('提示词已带回创作区，未提交真实任务。');break;case 'export':toast('原型展示导出入口，正式版本打包下载图片。');break;case 'logs':toast('示例日志：模型检查通过 → 等待派发 → 保留已有作品。');break;case 'folder':case 'service':toast('服务操作仅为演示，不操作本地进程或目录。');break;case 'language':toast('原型评估中文布局，正式版本保留中英文切换。');break;case 'dislike':artworks[selectedArt].disliked=true;renderGallery();toast('已标记不喜欢，原图保留。');break;}});
if(view==='batch')document.querySelector('.inspector .stack').append(document.querySelector('.ledger .dispatch'));
// Keep labels truthful and give the prototype a reusable prompt action, not a fake generation.
document.querySelectorAll('[data-action=regen]').forEach(b=>b.lastChild.textContent=' 复用提示词');
document.addEventListener('click',()=>{
    document.querySelectorAll('[data-action=regen]').forEach(b=>{if(b.textContent.includes('再抽一张'))b.textContent='复用提示词';});
    syncImageMetadata();
});
setRecipe();renderQueue();renderGallery();updateCount();syncImageMetadata();
